// Build HTML email from the search results
const body = $input.first().json.body;
const email = body.email;
const subject = body.subject || 'InsightHub - Search Results';
const agentName = body.agentName || 'AI Agent';
const results = body.results || [];

// Build HTML table from results
let tableHeaders = '';
let tableRows = '';

if (results.length > 0) {
  const keys = Object.keys(results[0]);
  tableHeaders = keys.map(k => `<th style="padding:12px 16px;text-align:left;background:#3b82f6;color:white;font-size:13px;text-transform:uppercase;letter-spacing:0.5px;">${k}</th>`).join('');
  tableRows = results.map(row => {
    const cells = keys.map(k => `<td style="padding:12px 16px;border-bottom:1px solid #e2e8f0;font-size:14px;color:#334155;">${row[k] || ''}</td>`).join('');
    return `<tr>${cells}</tr>`;
  }).join('');
}

const htmlBody = `
<!DOCTYPE html>
<html>
<head><meta charset="utf-8"></head>
<body style="font-family:'Segoe UI',Arial,sans-serif;background:#f1f5f9;padding:40px 20px;">
  <div style="max-width:900px;margin:0 auto;background:white;border-radius:12px;overflow:hidden;box-shadow:0 4px 24px rgba(0,0,0,0.08);">
    <div style="background:linear-gradient(135deg,#3b82f6,#10b981);padding:32px 40px;">
      <h1 style="color:white;margin:0;font-size:24px;">InsightHub</h1>
      <p style="color:rgba(255,255,255,0.85);margin:8px 0 0;font-size:14px;">Sri Lanka Telecom Mobitel - AI Sales Intelligence</p>
    </div>
    <div style="padding:32px 40px;">
      <h2 style="color:#1e293b;margin:0 0 8px;font-size:20px;">${agentName} Results</h2>
      <p style="color:#64748b;margin:0 0 24px;font-size:14px;">Generated on ${new Date().toLocaleString()}</p>
      <div style="overflow-x:auto;">
        <table style="width:100%;border-collapse:collapse;border-radius:8px;overflow:hidden;">
          <thead><tr>${tableHeaders}</tr></thead>
          <tbody>${tableRows}</tbody>
        </table>
      </div>
    </div>
    <div style="background:#f8fafc;padding:20px 40px;text-align:center;">
      <p style="color:#94a3b8;font-size:12px;margin:0;">This email was automatically generated by InsightHub AI. &copy; ${new Date().getFullYear()} Mobitel</p>
    </div>
  </div>
</body>
</html>
`;

return [{ json: { email, subject, htmlBody } }];
